 12345678910111213141516171819202122232425262728293031323334353637 PHP: // SplStack 类通过使用一个双向链表来提供栈的主要功能。[PHP 5 >= 5.3.0, PHP 7, PHP 8]
// https://www.php.net/manual/zh/class.splstack.php
class MyQueue {
    // 双栈模拟队列：In栈存储数据；Out栈辅助处理
    private $stackIn;
    private $stackOut;

    function __construct() {
        $this->stackIn = new SplStack();
        $this->stackOut = new SplStack();
    }

    // In: 1 2 3  <= push  
    function push($x) {
        $this->stackIn->push($x);
    }

    function pop() {
        $this->peek();
        return $this->stackOut->pop();
    }

    function peek() {
        if($this->stackOut->isEmpty()){
            $this->shift();
        }
        return $this->stackOut->top();
    }

    function empty() {
        return $this->stackOut->isEmpty() && $this->stackIn->isEmpty();
    }

    // 如果Out栈为空，把In栈数据压入Out栈
    // In: 1 2 3 => pop    push => 1 2 3 :Out  
    private function shift(){
        while(!$this->stackIn->isEmpty()){
            $this->stackOut->push($this->stackIn->pop());
        }
    }
    }
 1234567891011121314151617181920212223242526272829303132333435363738394041 Scala: class MyQueue() {
  import scala.collection.mutable
  val stackIn = mutable.Stack[Int]() // 负责出栈
  val stackOut = mutable.Stack[Int]() // 负责入栈

  // 添加元素
  def push(x: Int) {
    stackIn.push(x)
  }

  // 复用代码，如果stackOut为空就把stackIn的所有元素都压入StackOut
  def dumpStackIn(): Unit = {
    if (!stackOut.isEmpty) return
    while (!stackIn.isEmpty) {
      stackOut.push(stackIn.pop())
    }
  }

  // 弹出元素
  def pop(): Int = {
    dumpStackIn()
    stackOut.pop()
  }

  // 获取队头
  def peek(): Int = {
    dumpStackIn()
    val res: Int = stackOut.pop()
    stackOut.push(res)
    res
  }

  // 判断是否为空
  def empty(): Boolean = {
    stackIn.isEmpty && stackOut.isEmpty
  }

}
 1234567891011121314151617181920212223242526272829303132333435363738 Rust: struct MyQueue {
    stack_in: Vec<i32>,
    stack_out: Vec<i32>,
}
impl MyQueue {
    fn new() -> Self {
        MyQueue {
            stack_in: Vec::new(),
            stack_out: Vec::new(),
        }

    }

    fn push(&mut self, x: i32) {
        self.stack_in.push(x);
    }

    fn pop(&mut self) -> i32 {
        if self.stack_out.is_empty(){
            while !self.stack_in.is_empty() {
                self.stack_out.push(self.stack_in.pop().unwrap());
            }
        }
        self.stack_out.pop().unwrap()
    }

    fn peek(&mut self) -> i32 {
        let res = self.pop();
        self.stack_out.push(res);
        res
    }

    fn empty(&self) -> bool {
       self.stack_in.is_empty() && self.stack_out.is_empty()
    }
}
