 1234567891011121314151617181920212223242526272829303132 C: C：单队列 typedef struct Node {
    int val;
    struct Node *next;
} Node_t;

// 用单向链表实现queue
typedef struct {
    Node_t *head;
    Node_t *foot;
    int size;
} MyStack;

MyStack* myStackCreate() {
    MyStack *obj = (MyStack *)malloc(sizeof(MyStack));
    assert(obj);
    obj->head = NULL;
    obj->foot = NULL;
    obj->size = 0;
    return obj;
}

void myStackPush(MyStack* obj, int x) {

    Node_t *temp = (Node_t *)malloc(sizeof(Node_t));
    assert(temp);
    temp->val = x;
    temp->next = NULL;

    // 添加至queue末尾
    if (obj->foot) {
        obj->foot->next = temp;
    } else {
        obj->head = temp;
    }
    obj->foot = temp;
    obj->size++;
}

int myStackPop(MyStack* obj) {

    // 获取末尾元素
    int target = obj->foot->val;

    if (obj->head == obj->foot) {
        free(obj->foot);
        obj->head = NULL;
        obj->foot = NULL;
    } else {

        Node_t *prev = obj->head;
        // 移动至queue尾部节点前一个节点
        while (prev->next != obj->foot) {
            prev = prev->next;
        }

        free(obj->foot);
        obj->foot = prev;
        obj->foot->next = NULL;
    }

    obj->size--;
    return target;
}

int myStackTop(MyStack* obj) {
    return obj->foot->val;
}

bool myStackEmpty(MyStack* obj) {
    return obj->size == 0;
}

void myStackFree(MyStack* obj) {
    Node_t *curr = obj->head;
    while (curr != NULL) {
        Node_t *temp = curr->next;
        free(curr);
        curr = temp;
    }
    free(obj);
}

