  import scala.collection.mutable
  def evalRPN(tokens: Array[String]): Int = {
    val stack = mutable.Stack[Int]()    // 定义栈
    // 抽取运算操作，需要传递x,y，和一个函数
    def operator(x: Int, y: Int, f: (Int, Int) => Int): Int = f(x, y)
