        case "*" => stack.push(operator(stack.pop(), stack.pop(), _ * _))
        case "/" => {
          var pop1 = stack.pop()
          var pop2 = stack.pop()
          stack.push(operator(pop2, pop1, _ / _))
        }
        case _ => stack.push(token.toInt)   // 不是运算符就入栈
      }
    }
    // 最后返回栈顶，不需要加return关键字
    stack.pop() 
  }

